import os
from mem0 import Memory

def main():
    config = {
        "llm": {
            "provider": "openai",
            "config": {
                "model": "gpt-4o-mini"
            }
        },
        "vector_store": {
            "provider": "qdrant",
            "config": {
                "path": "/home/user/mem0_project/qdrant_db",
                "collection_name": "memories"
            }
        }
    }

    # Initialize Memory
    m = Memory.from_config(config)

    # Add memory
    print("Adding memory for user 'alice'...")
    result = m.add("I am learning how to build AI agents.", user_id="alice")
    print("Memory added successfully.")
    print(result)

    # Verify memory
    all_memories = m.get_all(user_id="alice")
    print("\nAll memories for alice:")
    if isinstance(all_memories, list):
        for memory in all_memories:
            # Depending on version text might be in 'text' or 'memory'
            text = memory.get('text') or memory.get('memory')
            print(f"- {text}")
    else:
        # Some versions might return a dict with 'memories' key
        memories = all_memories.get('memories', [])
        for memory in memories:
            text = memory.get('text') or memory.get('memory')
            print(f"- {text}")

if __name__ == "__main__":
    main()

